// crypto_test.go proves internal/aci's crypto is correct two ways: a
// self-consistent round-trip, and wire-interop with ACI's own published
// reference vector (docs/ARCHITECTURE-phase3-corrections.md section 2;
// buddy: apps/settle-aci-webhook/src/webhook/aci-decryption.service.spec.ts:6-11).
package aci

import (
	"encoding/hex"
	"encoding/json"
	"reflect"
	"testing"
)

func TestEncryptDecryptRoundTrip(t *testing.T) {
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}

	want := &Notification{
		Type: "PAYMENT",
		Payload: &Payload{
			ID:                    "8ac7a4a09dd44d76019dd475ba2172f2",
			MerchantTransactionID: "MTX-1",
			PaymentType:           "DB",
			PaymentBrand:          "VISA",
			PresentationAmount:    "25.00",
			PresentationCurrency:  "EUR",
			PluginType:            "SHOPFY",
			Source:                "WEB",
			ShortID:               "1234.5678",
			Timestamp:             "2026-01-01 12:00:00",
			ChannelName:           "channel-1",
			PaymentMethod:         "visa",
			NDC:                   "ndc-1",
			Result:                &Result{Code: "000.000.000", Description: "Transaction succeeded"},
			ResultDetails:         &ResultDetails{RiskOrderID: "risk-1", TransactionID: "txn-1", Action: "ACCEPT"},
			Card:                  &Card{Bin: "424242", Last4Digits: "4242", Holder: "Jane Doe", ExpiryMonth: "12", ExpiryYear: "2030", Type: "D", Country: "IE"},
		},
	}

	plaintext, err := json.Marshal(want)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}

	ciphertextHex, ivHex, tagHex, err := Encrypt(plaintext, key)
	if err != nil {
		t.Fatalf("encrypt: %v", err)
	}
	if ivHex == "" || tagHex == "" || ciphertextHex == "" {
		t.Fatalf("encrypt produced empty output: ciphertext=%q iv=%q tag=%q", ciphertextHex, ivHex, tagHex)
	}
	if n, err := hex.DecodeString(ivHex); err != nil || len(n) != 12 {
		t.Fatalf("iv must be 12 raw bytes hex-encoded, got %d bytes err=%v", len(n), err)
	}
	if n, err := hex.DecodeString(tagHex); err != nil || len(n) != 16 {
		t.Fatalf("tag must be 16 raw bytes hex-encoded, got %d bytes err=%v", len(n), err)
	}

	decrypted, err := Decrypt(ciphertextHex, ivHex, tagHex, key)
	if err != nil {
		t.Fatalf("decrypt: %v", err)
	}

	var got Notification
	if err := json.Unmarshal(decrypted, &got); err != nil {
		t.Fatalf("unmarshal decrypted: %v", err)
	}
	if !reflect.DeepEqual(&got, want) {
		t.Fatalf("round-trip mismatch:\ngot  %+v\nwant %+v", got, want)
	}

	// A tampered tag must fail to decrypt -- this IS ACI's auth check.
	badTag := tagHex[:len(tagHex)-2] + "00"
	if badTag == tagHex {
		badTag = "00" + tagHex[2:]
	}
	if _, err := Decrypt(ciphertextHex, ivHex, badTag, key); err == nil {
		t.Fatal("decrypt with tampered tag must fail")
	}
}

// ACI's own published reference vector, verbatim (not a secret -- ACI's
// public sample). Proves this package's AES-256-GCM implementation is
// wire-interoperable with buddy's real Node decryptor, not just
// self-consistent.
const (
	sampleKeyHex  = "232066076155F13C1027C662E62C0710977FA743C8D37766EF03DD94045C6981"
	sampleIVHex   = "C1751E8F5E9F2960CA4D6D6C"
	sampleTagHex  = "AA4732C45B76FC9C2F64355808462541"
	sampleBodyHex = ""
)

func TestDecryptKnownAnswerVector(t *testing.T) {
	key, err := hex.DecodeString(sampleKeyHex)
	if err != nil {
		t.Fatalf("decode sample key: %v", err)
	}
	if len(key) != 32 {
		t.Fatalf("sample key must be 32 bytes, got %d", len(key))
	}

	plaintext, err := Decrypt(sampleBodyHex, sampleIVHex, sampleTagHex, key)
	if err != nil {
		t.Fatalf("decrypt known-answer vector: %v", err)
	}

	var got Notification
	if err := json.Unmarshal(plaintext, &got); err != nil {
		t.Fatalf("unmarshal known-answer plaintext: %v", err)
	}
	if got.Payload == nil {
		t.Fatal("known-answer vector: payload is nil")
	}
	if got.Payload.MerchantTransactionID != "123412341235" {
		t.Fatalf("merchantTransactionId = %q, want 123412341235", got.Payload.MerchantTransactionID)
	}
	if got.Payload.PaymentType != "RX" {
		t.Fatalf("paymentType = %q, want RX", got.Payload.PaymentType)
	}
	if got.Payload.ResultDetails == nil || got.Payload.ResultDetails.RiskOrderID != "077869000001AD320260428101938765" {
		t.Fatalf("resultDetails.RiskOrderId = %+v, want 077869000001AD320260428101938765", got.Payload.ResultDetails)
	}
}
